-- [S14] The 15 Nebraska unaddressed majors: open HPVs (day zero, pollutants, agency), plus ICIS-Air formal actions since 2015 and informal actions since 2015, and stack-test fails since 2015
WITH f AS (SELECT PGM_SYS_ID, ANY_VALUE(FACILITY_NAME) AS NM, ANY_VALUE(CITY) AS CITY FROM LIBRARY_MARTS.ENVIRONMENT.ENVIRONMENT__FED_EPA_ICIS_AIR_ICIS_AIR_FACILITIES
  WHERE STATE='NE' GROUP BY 1 HAVING ANY_VALUE(AIR_POLLUTANT_CLASS_CODE)='MAJ' AND ANY_VALUE(AIR_OPERATING_STATUS_CODE)='OPR' AND ANY_VALUE(CURRENT_HPV) ILIKE 'Unaddressed%'),
v AS (SELECT PGM_SYS_ID, COUNT_IF(HPV_DAYZERO_DATE IS NOT NULL AND HPV_RESOLVED_DATE IS NULL) AS OPEN_HPV, MIN(IFF(HPV_RESOLVED_DATE IS NULL, HPV_DAYZERO_DATE, NULL)) AS OLDEST_OPEN, MAX(IFF(HPV_RESOLVED_DATE IS NULL, HPV_DAYZERO_DATE, NULL)) AS NEWEST_OPEN,
   LISTAGG(DISTINCT IFF(HPV_RESOLVED_DATE IS NULL AND HPV_DAYZERO_DATE IS NOT NULL, POLLUTANT_CODES, NULL), ';') AS OPEN_POLS, LISTAGG(DISTINCT IFF(HPV_RESOLVED_DATE IS NULL AND HPV_DAYZERO_DATE IS NOT NULL, AGENCY_TYPE_DESC, NULL), ';') AS OPEN_AGENCY,
   COUNT_IF(COALESCE(HPV_DAYZERO_DATE, EARLIEST_FRV_DETERM_DATE) >= '2015-01-01') AS VIOL_15
   FROM LIBRARY_MARTS.ENVIRONMENT.ENVIRONMENT__FED_EPA_ICIS_AIR_ICIS_AIR_VIOLATION_HISTORY WHERE PGM_SYS_ID IN (SELECT PGM_SYS_ID FROM f) GROUP BY 1),
fa AS (SELECT PGM_SYS_ID, COUNT(*) AS FORMAL_15, LISTAGG(STATE_EPA_FLAG || ':' || TO_VARCHAR(SETTLEMENT_ENTERED_DATE), ';') AS FA_LIST FROM LIBRARY_MARTS.ENVIRONMENT.ENVIRONMENT__FED_EPA_ICIS_AIR_ICIS_AIR_FORMAL_ACTIONS WHERE SETTLEMENT_ENTERED_DATE >= '2015-01-01' AND PGM_SYS_ID IN (SELECT PGM_SYS_ID FROM f) GROUP BY 1),
ia AS (SELECT PGM_SYS_ID, COUNT(*) AS INF_15 FROM LIBRARY_MARTS.ENVIRONMENT.ENVIRONMENT__FED_EPA_ICIS_AIR_ICIS_AIR_INFORMAL_ACTIONS WHERE ACHIEVED_DATE >= '2015-01-01' AND PGM_SYS_ID IN (SELECT PGM_SYS_ID FROM f) GROUP BY 1),
st AS (SELECT PGM_SYS_ID, COUNT(DISTINCT IFF(AIR_STACK_TEST_STATUS_CODE='FAI', ACTUAL_END_DATE, NULL)) AS FAIL_DAYS_15 FROM LIBRARY_MARTS.ENVIRONMENT.ENVIRONMENT__FED_EPA_ICIS_AIR_ICIS_AIR_STACK_TESTS WHERE ACTUAL_END_DATE >= '2015-01-01' AND PGM_SYS_ID IN (SELECT PGM_SYS_ID FROM f) GROUP BY 1)
SELECT f.NM, f.CITY, v.OPEN_HPV, v.OLDEST_OPEN, v.NEWEST_OPEN, v.OPEN_POLS, v.OPEN_AGENCY, v.VIOL_15, COALESCE(fa.FORMAL_15,0) AS FORMAL_15, fa.FA_LIST, COALESCE(ia.INF_15,0) AS INF_15, COALESCE(st.FAIL_DAYS_15,0) AS FAIL_DAYS_15
FROM f LEFT JOIN v USING (PGM_SYS_ID) LEFT JOIN fa USING (PGM_SYS_ID) LEFT JOIN ia USING (PGM_SYS_ID) LEFT JOIN st USING (PGM_SYS_ID) ORDER BY v.OLDEST_OPEN
